bool flag = true;   // переменная равна истине
bool empty = false;   // переменная равна лжи
// Неявное преобразование: 0 становится false, любое другое число — true

#include <string>

std::string s = "Hello";                                    // создание строки
std::string s2 = "World"s;                                  // user-defined literal (C++14, нужен <string>)

// Запрещает narrowing conversions (сужающие преобразования)
int x1{3.14};        // ОШИБКА: не могу преобразовать double в int без потери точности
int x2 = 3.14;       // OK, но компилятор может выдать предупреждение с -Wnarrowing

// Работает со всеми типами одинаково
std::vector<int> v{1, 2, 3};
std::string s{"text"};
auto p = std::make_unique<int>(42);

struct Point {
    int x = 0;        // default member initializer (C++11) — если не указано иное, x будет 0
    int y = 0;
    Point(int x_, int y_) : x(x_), y(y_) {}  // member initializer list — явная инициализация
};

Point p1;        // (0, 0) — оба поля получили значения по умолчанию
Point p2{3, 4};  // (3, 4) — явная инициализация через конструктор

const int MAX_SIZE = 100;
// MAX_SIZE = 200;  // ОШИБКА: нельзя изменить const-переменную

const int* p1 = &MAX_SIZE;  // указатель на const int (нельзя изменить значение через указатель)
int* const p2 = new int(5); // const указатель на int (нельзя изменить сам указатель)
const int* const p3 = &MAX_SIZE;  // const указатель на const int (ничего нельзя менять)

constexpr int square(int x) { return x * x; }
constexpr int SZ = square(5);  // 25, вычисляется при компиляции
int arr[SZ];  // OK: SZ — константа времени компиляции, можно использовать для размера массива

// constexpr-переменные неявно являются const
constexpr double PI = 3.14159;

// Когда тип важен для читаемости кода:
std::vector<int> v = get_vector();  // лучше явно — читающий сразу знает тип
// vs
auto v = get_vector();  // тип неочевиден без просмотра get_vector()

// Когда нужен конкретный тип:
double d = 1 / 2;      // 0 (целочисленное деление! int / int = int)
auto d2 = 1.0 / 2.0;   // 0.5 (float / float = double)

double d = 3.14;
int i1 = static_cast<int>(d);      // 3 — отбрасывание дробной части
int i2 = static_cast<int>(d + 0.5); // 3 — округление до ближайшего

// Указатели
void* pv = &d;
double* pd = static_cast<double*>(pv);

// enum class
enum class Color { Red, Green };
int c = static_cast<int>(Color::Red);  // 0 — безопасное приведение enum к int

// (Type)value или Type(value) — комбинируют static_cast + const_cast + reinterpret_cast
int i = (int)d;        // ПЛОХО: скрывает const_cast/reinterpret_cast
int j = int(d);        // ТОЖЕ ПЛОХО — та же проблема

// Только для низкоуровневого кода
int i = 0x41424344;
char* c = reinterpret_cast<char*>(&i);  // "ABCD" в little-endian

void legacy_api(char* s);  // старый API без const

const char* cs = "hello";
// legacy_api(cs);  // ОШИБКА: нельзя передать const char* в функцию, ожидающую char*
legacy_api(const_cast<char*>(cs));  // OK, но опасно: если legacy_api модифицирует строку — UB
